#!/usr/bin/env python3
# Piece 4-C - the money door. createInvoice / recordPayment / updateInvoice go
# through kriya_money_edit (owed vs received, witnessed). updateExpense gains its
# amount path. Stacks on 4-B. Anchored + idempotent.
import base64, sys, os
PATH = "lib/vendor/api/vendor.ts"
def d(s): return base64.b64decode(s).decode("utf-8")
EDITS = [
    ("createInvoice", "", ""),
    ("updateInvoice", "", ""),
    ("recordPayment", "", ""),
    ("updateExpense", "", "")
]
if not os.path.exists(PATH):
    print("FATAL: %s not found (run from dreamos-pwa root)." % PATH); sys.exit(1)
text = open(PATH, encoding="utf-8").read()
applied = skipped = 0
for label, o_b64, n_b64 in EDITS:
    old, new = d(o_b64), d(n_b64)
    if new in text:
        print("SKIP  [%s] already applied." % label); skipped += 1; continue
    c = text.count(old)
    if c == 1: text = text.replace(old, new); applied += 1; print("OK    [%s]" % label)
    elif c == 0: print("SKIP  [%s] anchor NOT FOUND - untouched." % label); skipped += 1
    else: print("SKIP  [%s] anchor x%d - untouched." % (label, c)); skipped += 1
open(PATH, "w", encoding="utf-8").write(text)
ME = "/money-edit" + chr(96)
checks = [
  ("createInvoice -> money-edit",  "export async function createInvoice" in text and "amount_received: String(received), amount_pending: String(pending)" in text),
  ("invoice resolves binder",      "body.client_id || body.lead_id || null" in text and "stage: 'client'," in text),
  ("recordPayment reads first",    "// Ground-truth before mutation" in text and "const led = await fetchLedger(v);" in text and "(b.amount_received ?? 0) + pay" in text),
  ("recordPayment new absolutes",  "Math.max(0, (b.amount_pending ?? 0) - pay)" in text),
  ("updateInvoice money path",     "export async function updateInvoice" in text and "body.amount_total != null || body.amount_advance != null" in text),
  ("updateExpense amount path",    "if (body.amount != null) {" in text and "amount: String(body.amount), direction: 'out'," in text),
  ("money-edit endpoint used",     ME in text),
  ("pdf_pending honest",           "pdf_pending: true };" in text),
  ("no InvoiceState import needed","const status = " in text),
  ("dead invoice POST gone",       "postJson<CreateInvoiceResponse | ApiErr>('/api/v2/vendor/invoices', body)" not in text),
  ("dead payments POST gone",      "/api/v2/vendor/invoices/${invoiceId}/payments" not in text),
  ("dead invoice PATCH gone",      "patchJson<UpdateInvoiceResponse | ApiErr>(" + chr(96) + "/api/v2/vendor/invoices/" not in text),
  ("PDF/cancel UNTOUCHED (Step10)","/api/v2/vendor/invoices/${invoiceId}/pdf" in text and "/api/v2/vendor/invoices/${invoiceId}/cancel" in text),
]
print(chr(10) + "-- verification --")
allok = True
for n,p in checks: print("  %s %s" % ("PASS" if p else "FAIL", n)); allok = allok and p
print(chr(10) + "(%d applied, %d skipped)" % (applied, skipped))
print("ALL CHECKS PASSED" if allok else "SOME CHECKS FAILED")
sys.exit(0 if allok else 2)
